package com.wedo.backend.discussion.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="activity_comments") public class ActivityCommentEntity { @Id private UUID id; @Column(name="activity_id",nullable=false) private UUID activityId; @Column(name="author_id",nullable=false) private UUID authorId; @Column(name="parent_comment_id") private UUID parentCommentId; @Column(nullable=false) private String content; @Column(name="is_edited",nullable=false) private boolean edited; @Column(name="edited_at") private Instant editedAt; @Column(name="is_deleted",nullable=false) private boolean deleted; @Column(name="deleted_at") private Instant deletedAt; @Column(name="deleted_by") private UUID deletedBy; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; protected ActivityCommentEntity(){} public ActivityCommentEntity(UUID id,UUID activityId,UUID authorId,UUID parentCommentId,String content,Instant now){this.id=id;this.activityId=activityId;this.authorId=authorId;this.parentCommentId=parentCommentId;this.content=content;this.createdAt=now;this.updatedAt=now;} public UUID getId(){return id;} public UUID getActivityId(){return activityId;} public UUID getAuthorId(){return authorId;} public UUID getParentCommentId(){return parentCommentId;} public String getContent(){return content;} public boolean isEdited(){return edited;} public Instant getEditedAt(){return editedAt;} public boolean isDeleted(){return deleted;} public Instant getDeletedAt(){return deletedAt;} public UUID getDeletedBy(){return deletedBy;} public Instant getCreatedAt(){return createdAt;} public void edit(String content,Instant now){this.content=content;this.edited=true;this.editedAt=now;this.updatedAt=now;} public void delete(UUID actor,Instant now){this.deleted=true;this.deletedAt=now;this.deletedBy=actor;this.updatedAt=now;} }
